def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]
    my_c = 0
    my_d = 0
    op_c = 0
    op_d = 0
    for i in range(n):
        if me[i] == 'C':
            my_c += 1
        else:
            my_d += 1
        if op[i] == 'C':
            op_c += 1
        else:
            op_d += 1

    # Late game: exploit persistent cooperators, defend against defectors.
    if n >= 88:
        if op_d == 0:
            return 'D'
        if op_d <= 2 and op_c >= n - 2:
            return 'D' if rng.random() < 0.8 else 'C'
        if op_c == 0:
            return 'D'
        # if we're clearly worse off vs a defector, defect
        if op_d * 2 >= n and op_c * 4 < n:
            return 'D'

    # Pure cooperator detection (with tolerance for early probe).
    if op_d == 0:
        if n < 8:
            return 'C'
        # probe occasionally, then exploit if they keep cooperating
        if op_c >= 20 and my_d >= 1 and rng.random() < 0.7:
            return 'D'
        if rng.random() < 0.06:
            return 'D'
        return 'C'

    # Pure defector: defend.
    if op_c == 0:
        return 'D'

    # Mostly cooperative opponent: keep cooperating, small probes.
    if op_c * 4 >= n * 3:
        # punish only recent defection
        recent = op[-4:] if n >= 4 else op
        rd = 0
        for a in recent:
            if a == 'D':
                rd += 1
        if rd >= 2:
            return 'D'
        if n < 95 and rng.random() < 0.04:
            return 'D'
        return 'C'

    # Mostly defective opponent: exploit/defend mix.
    if op_d * 4 >= n * 3:
        if op[-1] == 'C' and rng.random() < 0.5:
            return 'C'
        if op_d >= 10 and op_c >= 3 and rng.random() < 0.25:
            return 'C'
        return 'D'

    # Mixed regime: track recent window.
    w = 10 if n >= 10 else n
    recent_op = op[-w:]
    roc = 0
    rod = 0
    for a in recent_op:
        if a == 'C':
            roc += 1
        else:
            rod += 1

    recent_me = me[-w:]
    rmc = 0
    rmd = 0
    for a in recent_me:
        if a == 'C':
            rmc += 1
        else:
            rmd += 1

    last_me = me[-1]
    last_op = op[-1]

    # If opponent heavily cooperative recently, cooperate unless provoked.
    if roc * 4 >= w * 3:
        if last_op == 'D' and rng.random() < 0.7:
            return 'D'
        if n < 92 and rng.random() < 0.03:
            return 'D'
        return 'C'

    # If opponent heavily defective recently, defect.
    if rod * 4 >= w * 3:
        if last_op == 'C' and roc >= 2 and rng.random() < 0.3:
            return 'C'
        return 'D'

    # Mutual defection spiral: try to break out occasionally.
    if last_me == 'D' and last_op == 'D':
        if rmd >= 3 and rod >= 3 and rng.random() < 0.45:
            return 'C'
        return 'D'

    # Opponent just defected.
    if last_op == 'D':
        if roc >= 5 and rng.random() < 0.3:
            return 'C'
        if last_me == 'D':
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        return 'D'

    # Opponent just cooperated.
    if last_me == 'D':
        # We exploited; probe whether cooperation holds, but be cautious.
        if my_d > op_d + 3:
            return 'C'
        if rng.random() < 0.25:
            return 'D'
        return 'C'

    # Default: cooperate.
    if n < 95 and rng.random() < 0.02:
        return 'D'
    return 'C'
